-- Undoes 050: deletes the drop_data rows 050 inserted (recorded in bb_drops_050_rows; a pair that was already there before
-- 050, such as a Monster Book card row, is left alone). Applying it twice changes nothing. A running server needs
-- !reloaddrops. Generated by tools/economy/gen_bb_drops.py.
CREATE TABLE IF NOT EXISTS mapleroot_integration_migrations (
  migration_id varchar(100) PRIMARY KEY,
  applied_at timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP
) ENGINE=InnoDB;
CREATE TABLE IF NOT EXISTS bb_drops_050_rows (
  dropperid int NOT NULL,
  itemid    int NOT NULL,
  PRIMARY KEY (dropperid, itemid)
) ENGINE=InnoDB;

DELETE d FROM drop_data d JOIN bb_drops_050_rows r ON r.dropperid = d.dropperid AND r.itemid = d.itemid;
DELETE FROM bb_drops_050_rows;
DELETE FROM mapleroot_integration_migrations WHERE migration_id = '050-bb-drop-tables';
